import random

def evaluate(current_reputation, observation, my_history, round_num):
    # Update reputation based on observed action with recency weighting
    action = observation['action']

    if action == 'cooperate':
        new_reputation = current_reputation + 0.15
    else:  # defect
        new_reputation = current_reputation - 0.15

    # Apply exponential decay to give more weight to recent actions
    decay = 0.90
    new_reputation = new_reputation * decay + current_reputation * (1 - decay)

    # Clamp reputation to valid range
    return max(-1.0, min(1.0, new_reputation))


def decide(recipient_reputation, round_num, my_history):
    # Cooperate based on recipient's reputation with adaptive threshold
    # Higher reputation -> higher chance to cooperate

    if recipient_reputation > 0.2:
        return True  # Strongly cooperate with good reputation
    elif recipient_reputation < -0.2:
        return False  # Definitely defect with bad reputation
    else:
        # For neutral reputation, use mixed strategy based on round
        # Early rounds: more cooperative to build reputation
        # Later rounds: more selective
        if round_num < 20:
            return random.random() < 0.7
        else:
            return random.random() < 0.3

